import{_ as e,o as r,f as t,a6 as o}from"./chunks/framework.BFhbG0o2.js";const u=JSON.parse('{"title":"个人资源库比普通博客更重要","description":"资源的价值来自验证、分类和再次进入项目，而不是收藏数量。","frontmatter":{"title":"个人资源库比普通博客更重要","description":"资源的价值来自验证、分类和再次进入项目，而不是收藏数量。","pageClass":"page-article-detail","status":"published"},"headers":[],"relativePath":"blog/personal-resource-library.md","filePath":"blog/personal-resource-library.md"}'),l={name:"blog/personal-resource-library.md"};function i(s,a,n,h,p,d){return r(),t("div",null,[...a[0]||(a[0]=[o('<h1 id="个人资源库比普通博客更重要" tabindex="-1">个人资源库比普通博客更重要 <a class="header-anchor" href="#个人资源库比普通博客更重要" aria-label="Permalink to &quot;个人资源库比普通博客更重要&quot;">​</a></h1><p>在信息可以被快速生成的环境里，收藏更多链接并不会自动形成优势。真正有价值的是你如何筛选、验证和重新使用这些信息。</p><h2 id="按使用场景而不是平台分类" tabindex="-1">按使用场景而不是平台分类 <a class="header-anchor" href="#按使用场景而不是平台分类" aria-label="Permalink to &quot;按使用场景而不是平台分类&quot;">​</a></h2><p>“来自 Midjourney”或“来自某个网站”不是最有用的分类。更好的方式是按产品图、品牌提案、批量内容、交付检查等场景组织，这样项目开始时可以直接找到入口。</p><h2 id="每条资源都需要状态" tabindex="-1">每条资源都需要状态 <a class="header-anchor" href="#每条资源都需要状态" aria-label="Permalink to &quot;每条资源都需要状态&quot;">​</a></h2><p>记录来源、访问方式、授权范围、最后验证时间和适用边界。失效链接、来源不明的模型或无法解释授权的素材，不应该继续出现在公开资源库中。</p><h2 id="资源必须连接实践" tabindex="-1">资源必须连接实践 <a class="header-anchor" href="#资源必须连接实践" aria-label="Permalink to &quot;资源必须连接实践&quot;">​</a></h2><p>Prompt 模板应该链接使用它的工作流，检查清单应该链接实际案例。只有当资源帮助完成一次任务，它才从“收藏”变成了资产。</p><h2 id="小而可信比大而失真更重要" tabindex="-1">小而可信比大而失真更重要 <a class="header-anchor" href="#小而可信比大而失真更重要" aria-label="Permalink to &quot;小而可信比大而失真更重要&quot;">​</a></h2><p>资源库可以从两三项真正有效的内容开始。持续验证和复盘，比一次性铺满看似丰富的下载页更能建立信任。</p><h2 id="关联内容" tabindex="-1">关联内容 <a class="header-anchor" href="#关联内容" aria-label="Permalink to &quot;关联内容&quot;">​</a></h2><ul><li><a href="/resources/mj-prompt.html">商业视觉 Prompt 结构</a></li><li><a href="/resources/notion.html">AI 项目复盘清单</a></li><li><a href="/portfolio/exhibition-visual.html">德国水处理展会视觉体系</a></li></ul><p><a href="/blog/">← 返回方法与洞察</a></p>',13)])])}const b=e(l,[["render",i]]);export{u as __pageData,b as default};
